core_reasoning_2:
\section*{Claim}
For a product configuration on a contractible loop with holonomy $h\in G$, the condition
\[
\Lambda_\ell^\alpha |\{g\}\rangle=d_\alpha |\{g\}\rangle\quad\text{for every }\alpha\in\operatorname{Rep}(G)
\]
implies $h=1$. Conversely, if $h=1$, then the same eigenvalue equation holds for every $\alpha$.

\section*{Premises}
\begin{align*}
(P1)\;&G\text{ is finite, }1\in G\text{ is the identity, and }\alpha\in\operatorname{Rep}(G)\text{ has dimension }d_\alpha.\\
(P2)\;&\Lambda_\ell^\alpha |\{g\}\rangle=\chi_\alpha(h)|\{g\}\rangle,\text{ where }h\in G\text{ is the loop holonomy.}\\
(P3)\;&d_\alpha=\chi_\alpha(1).\\
(P4)\;&\sum_{\alpha\in\operatorname{Rep}(G)}\chi_\alpha(u)\overline{\chi_\alpha(v)}=|C_u|\delta_{[u],[v]},\quad u,v\in G,\\
&\text{where }C_u:=\{x\in G:xu=ux\}\text{ and }[u]:=\{xux^{-1}:x\in G\}.\\
(P5)\;&[1]=\{1\}.\\
(P6)\;&\Lambda_\ell^\alpha |\{g\}\rangle=d_\alpha |\{g\}\rangle\text{ for every }\alpha\in\operatorname{Rep}(G).
\end{align*}

\section*{Derivation}
\begin{align*}
\chi_\alpha(h)|\{g\}\rangle
&=\Lambda_\ell^\alpha |\{g\}\rangle &&\text{by (P2)}\\
&=d_\alpha |\{g\}\rangle &&\text{by (P6)}\\
&=\chi_\alpha(1)|\{g\}\rangle &&\text{by (P3).}
\end{align*}
Since $|\{g\}\rangle\ne 0$, this gives
\begin{align*}
\chi_\alpha(h)&=\chi_\alpha(1)\qquad\forall\alpha\in\operatorname{Rep}(G). &&\text{scalar equality}
\end{align*}
Therefore
\begin{align*}
|C_h|\delta_{[h],[1]}
&=\sum_\alpha \chi_\alpha(h)\overline{\chi_\alpha(1)} &&\text{by (P4)}\\
&=\sum_\alpha \chi_\alpha(1)\overline{\chi_\alpha(1)} &&\text{by the previous equality}\\
&=|C_1|\delta_{[1],[1]} &&\text{by (P4) with }u=v=1\\
&=|G|. &&\text{because }C_1=G
\end{align*}
Since $|C_h|\le |G|$ and the right-hand side is nonzero, $\delta_{[h],[1]}=1$. Hence
\begin{align*}
[h]&=[1] &&\text{definition of }\delta_{[h],[1]}\\
&=\{1\} &&\text{by (P5),}
\end{align*}
so $h=1$. Conversely, if $h=1$, then
\begin{align*}
\Lambda_\ell^\alpha |\{g\}\rangle
&=\chi_\alpha(h)|\{g\}\rangle &&\text{by (P2)}\\
&=\chi_\alpha(1)|\{g\}\rangle &&\text{using }h=1\\
&=d_\alpha |\{g\}\rangle &&\text{by (P3).}
\end{align*}

\section*{Final Result}
\[
\boxed{\left(\forall\alpha,\ \Lambda_\ell^\alpha |\{g\}\rangle=d_\alpha |\{g\}\rangle\right)\Longleftrightarrow h=1}
\]
\hfill$\blacksquare$

core_reasoning_3:
\section*{Claim}
Let $M=X\cup Y$ be a bipartition with boundary $\partial=X\cap Y$, and let $A\subset\partial$ contain one base point per connected component of $\partial$. For loop-symmetric states, the coefficient matrix $W$ belongs to the block vector space
\[
\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\varphi)||G|^{|V_X|}\times |r_Y^{-1}(\varphi)||G|^{|V_Y|}}.
\]

\section*{Premises}
\begin{align*}
(P1)\;&G\text{ is finite; }V_X,V_Y,V_\partial\text{ are the interior and boundary vertex sets of the bipartition.}\\
(P2)\;&A\subset V_\partial\text{ contains exactly one base point per connected component of }\partial.\\
(P3)\;&\text{Loop-symmetric basis states on }M\text{ are }|\{g\}_{V\setminus A},\Phi\rangle,
\quad \Phi\in\operatorname{Hom}(\pi_1(M,A),G).\\
(P4)\;&\text{Subsystem basis states are }|\{g\}_{\overline V_X\setminus A},\varphi_X\rangle
\text{ and }|\{g\}_{\overline V_Y\setminus A},\varphi_Y\rangle.\\
(P5)\;&\operatorname{Hom}(\pi_1(M,A),G)
\cong \{(\varphi_X,\varphi_Y):r_X(\varphi_X)=r_Y(\varphi_Y)\}.\\
(P6)\;&\operatorname{Im}:=r_X(\operatorname{Hom}(\pi_1(X,A),G))\cap r_Y(\operatorname{Hom}(\pi_1(Y,A),G)).\\
(P7)\;&\text{For fixed }\varphi\in\operatorname{Im},\text{ there are }|r_X^{-1}(\varphi)|\text{ choices of }\varphi_X\text{ and }|r_Y^{-1}(\varphi)|\text{ choices of }\varphi_Y.\\
(P8)\;&\text{For fixed topological labels, the independent geometric choices are }|G|^{|V_X|}\text{ in }X,
\ |G|^{|V_Y|}\text{ in }Y,\text{ and }|G|^{|V_\partial|-|A|}\text{ common boundary choices.}
\end{align*}

\section*{Derivation}
By (P5), every admissible global topological class is represented by a pair with a shared boundary value. Thus
\begin{align*}
\Phi\in\operatorname{Hom}(\pi_1(M,A),G)
&\Longleftrightarrow \exists\varphi\in\operatorname{Im}\text{ such that }\varphi_X\in r_X^{-1}(\varphi),\ \varphi_Y\in r_Y^{-1}(\varphi) &&\text{by (P5),(P6)}\\
&\Longleftrightarrow \Phi=(\varphi_X,\varphi_Y)\text{ with }\varphi_X\in r_X^{-1}(\varphi),\ \varphi_Y\in r_Y^{-1}(\varphi). &&\text{fiber notation}
\end{align*}
For a fixed $\varphi$, the number of row labels in $X$ is
\begin{align*}
N_X(\varphi)&:=|r_X^{-1}(\varphi)|\,|G|^{|V_X|} &&\text{by (P7),(P8),}
\end{align*}
and the number of column labels in $Y$ is
\begin{align*}
N_Y(\varphi)&:=|r_Y^{-1}(\varphi)|\,|G|^{|V_Y|} &&\text{by (P7),(P8).}
\end{align*}
The common non-base-point boundary gauge choices give
\begin{align*}
N_\partial&:=|G|^{|V_\partial|-|A|} &&\text{by (P8)}
\end{align*}
independent copies of the same topological block. Therefore the full coefficient matrix space decomposes as
\begin{align*}
\mathcal{W}
&=\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{N_\partial}\mathbb{C}^{N_X(\varphi)\times N_Y(\varphi)} &&\text{assemble disjoint boundary sectors}\\
&=\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\varphi)||G|^{|V_X|}\times |r_Y^{-1}(\varphi)||G|^{|V_Y|}} &&\text{substitute }N_X,N_Y,N_\partial.
\end{align*}
Equivalently, separating topological and geometric factors gives
\begin{align*}
\mathcal{W}
&\cong \left(\bigoplus_{\varphi\in\operatorname{Im}}\mathbb{C}^{|r_X^{-1}(\varphi)|\times |r_Y^{-1}(\varphi)|}\right)
\otimes\left(\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}\mathbb{C}^{|G|^{|V_X|}\times |G|^{|V_Y|}}\right). &&\text{factor dimensions}
\end{align*}

\section*{Final Result}
\[
\boxed{\mathcal{W}=\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\varphi)||G|^{|V_X|}\times |r_Y^{-1}(\varphi)||G|^{|V_Y|}}}
\]
\hfill$\blacksquare$

core_reasoning_4:
\section*{Claim}
For the nontrivial bipartition of the torus $T^2$ into two cylinders with two boundary components and two base points, the loop-symmetric coefficient matrix has block structure
\[
\bigoplus_{c\in G}\bigoplus_{j=1}^{|[c]|\,|G|^{|V_\partial|-2}}
\mathbb{C}^{|C_c||G|^{|V_X|}\times |C_c||G|^{|V_Y|}},
\]
where $C_c:=\{g\in G:gc=cg\}$ and $[c]:=\{gcg^{-1}:g\in G\}$.

\section*{Premises}
\begin{align*}
(P1)\;&X\cong \Sigma_{0,2},\quad Y\cong \Sigma_{0,2},\quad \partial=S^1\sqcup S^1,
\quad |A|=2.\\
(P2)\;&\operatorname{Hom}(\pi_1(\partial,A),G)\cong G^2,\text{ with boundary label }(a_1,a_2).\\
(P3)\;&r_X(a_1,b_X)=(a_1,b_X^{-1}a_1b_X),\qquad r_Y(a_1,b_Y)=(a_1,b_Ya_1b_Y^{-1}).\\
(P4)\;&C_c:=\{g\in G:gc=cg\},\qquad [c]:=\{gcg^{-1}:g\in G\}.\\
(P5)\;&|\{a_2\in G:a_2\in[c]\}|=|[c]|.\\
(P6)\;&|\{b\in G:b^{-1}cb=a_2\}|=|C_c|\quad\text{whenever }a_2\in[c].\\
(P7)\;&\text{The general loop-symmetric block formula is }\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\varphi)||G|^{|V_X|}\times |r_Y^{-1}(\varphi)||G|^{|V_Y|}}.
\end{align*}

\section*{Derivation}
Let $\varphi=(a_1,a_2)\in G^2$. For $X$,
\begin{align*}
r_X^{-1}(a_1,a_2)
&=\{(a_1,b_X):b_X^{-1}a_1b_X=a_2\} &&\text{by (P3)}.
\end{align*}
This set is nonempty exactly when $a_2\in[a_1]$. If $a_1=c$ and $a_2\in[c]$, then
\begin{align*}
|r_X^{-1}(c,a_2)|&=|\{b_X\in G:b_X^{-1}cb_X=a_2\}| &&\text{definition of the fiber}\\
&=|C_c| &&\text{by (P6).}
\end{align*}
Similarly,
\begin{align*}
|r_Y^{-1}(c,a_2)|&=|\{b_Y\in G:b_Ycb_Y^{-1}=a_2\}| &&\text{by (P3)}\\
&=|C_c| &&\text{same centralizer counting as (P6).}
\end{align*}
For a fixed $c$, the admissible choices of $a_2$ are precisely the elements of $[c]$, hence
\begin{align*}
\#\{a_2:(c,a_2)\in\operatorname{Im}\}&=|[c]| &&\text{by (P5).}
\end{align*}
For each admissible $(c,a_2)$, (P7) gives $|G|^{|V_\partial|-2}$ geometric boundary copies. Grouping these copies by $c$ gives
\begin{align*}
\mathcal{W}_{T^2}
&=\bigoplus_{c\in G}\bigoplus_{a_2\in[c]}\bigoplus_{j=1}^{|G|^{|V_\partial|-2}}
\mathbb{C}^{|C_c||G|^{|V_X|}\times |C_c||G|^{|V_Y|}} &&\text{by (P7)}\\
&=\bigoplus_{c\in G}\bigoplus_{j=1}^{|[c]|\,|G|^{|V_\partial|-2}}
\mathbb{C}^{|C_c||G|^{|V_X|}\times |C_c||G|^{|V_Y|}} &&\text{combine }|[c]|\text{ equal-size sectors.}
\end{align*}

\section*{Final Result}
\[
\boxed{\mathcal{W}_{T^2}=\bigoplus_{c\in G}\bigoplus_{j=1}^{|[c]|\,|G|^{|V_\partial|-2}}
\mathbb{C}^{|C_c||G|^{|V_X|}\times |C_c||G|^{|V_Y|}}}
\]
\hfill$\blacksquare$

core_reasoning_5:
\section*{Claim}
For a connected orientable genus-$\gamma$ surface bipartition
\[
M=\Sigma_{\gamma,0},\qquad X=\Sigma_{\gamma_X,n},\qquad Y=\Sigma_{\gamma_Y,n},\qquad \gamma=\gamma_X+\gamma_Y+n-1,
\]
with $n$ boundary circles, the block structure is
\[
\bigoplus_{c\in G^n}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c)|G|^{|V_Y|}},
\]
where
\[
R_{\gamma,n}(c):=\sum_{\alpha\in\operatorname{Rep}(G)}\left(\frac{|G|}{d_\alpha}\right)^{2\gamma+n-2}\prod_{i=1}^n\chi_\alpha(c_i).
\]

\section*{Premises}
\begin{align*}
(P1)\;&c=(c_1,\ldots,c_n)\in G^n\text{ records the holonomies of the }n\text{ boundary circles.}\\
(P2)\;&\text{For }S\in\{X,Y\}\text{ with genus }\gamma_S,\ |r_S^{-1}(c)|=R_{\gamma_S,n}(c).\\
(P3)\;&R_{\gamma,n}(c):=\sum_{\alpha\in\operatorname{Rep}(G)}\left(\frac{|G|}{d_\alpha}\right)^{2\gamma+n-2}\prod_{i=1}^n\chi_\alpha(c_i).\\
(P4)\;&|A|=n.\\
(P5)\;&\text{The general loop-symmetric block formula is }\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\varphi)||G|^{|V_X|}\times |r_Y^{-1}(\varphi)||G|^{|V_Y|}}.\\
(P6)\;&\operatorname{Im}=\{c\in G^n:R_{\gamma_X,n}(c)>0\text{ and }R_{\gamma_Y,n}(c)>0\};\text{ zero-size summands may be omitted.}
\end{align*}

\section*{Derivation}
For this surface bipartition, the boundary Hom label is exactly $c\in G^n$. Thus
\begin{align*}
\varphi&=c &&\text{by (P1).}
\end{align*}
Using the preimage-count formula for each side,
\begin{align*}
|r_X^{-1}(\varphi)|&=|r_X^{-1}(c)| &&\text{substitute }\varphi=c\\
&=R_{\gamma_X,n}(c) &&\text{by (P2),}\\
|r_Y^{-1}(\varphi)|&=|r_Y^{-1}(c)| &&\text{substitute }\varphi=c\\
&=R_{\gamma_Y,n}(c) &&\text{by (P2).}
\end{align*}
The number of common non-base-point boundary gauge sectors is
\begin{align*}
|G|^{|V_\partial|-|A|}&=|G|^{|V_\partial|-n} &&\text{by (P4).}
\end{align*}
Substituting these three quantities into the general block formula gives
\begin{align*}
\mathcal{W}_{\Sigma_{\gamma,0}}
&=\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c)|G|^{|V_Y|}} &&\text{by (P5)}\\
&=\bigoplus_{c\in G^n}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c)|G|^{|V_Y|}} &&\text{by (P6), allowing zero-size omissions.}
\end{align*}
Finally, (P3) gives the explicit character expression for both $R_{\gamma_X,n}$ and $R_{\gamma_Y,n}$.

\section*{Final Result}
\[
\boxed{\mathcal{W}_{\Sigma_{\gamma,0}}=\bigoplus_{c\in G^n}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c)|G|^{|V_Y|}},\quad
R_{\gamma,n}(c)=\sum_\alpha\left(\frac{|G|}{d_\alpha}\right)^{2\gamma+n-2}\prod_{i=1}^n\chi_\alpha(c_i)}
\]
\hfill$\blacksquare$

core_reasoning_6:
\section*{Claim}
For the Klein bottle bipartition into two Mobius bands, where each subsystem is $N_{1,1}$ and the common boundary is a single circle, the loop-symmetric coefficient matrix has block structure
\[
\bigoplus_{c\in G:K(c)>0}\bigoplus_{j=1}^{|G|^{|V_\partial|-1}}
\mathbb{C}^{K(c)|G|^{|V_X|}\times K(c)|G|^{|V_Y|}},
\]
where
\[
K(c):=|\{g\in G:g^2=c\}|=\sum_{\alpha\in\operatorname{Rep}(G)}\iota_\alpha\chi_\alpha(c),
\qquad
\iota_\alpha:=\frac{1}{|G|}\sum_{g\in G}\chi_\alpha(g^2).
\]

\section*{Premises}
\begin{align*}
(P1)\;&M=N_2,\quad X=N_{1,1},\quad Y=N_{1,1},\quad \partial=S^1,\quad |A|=1.\\
(P2)\;&\text{For }S\in\{X,Y\},\text{ the boundary restriction sends a subsystem holonomy }g\in G\text{ to }g^2.\\
(P3)\;&K(c):=|\{g\in G:g^2=c\}|.\\
(P4)\;&\delta_{u,c}=\frac{1}{|G|}\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\chi_\alpha(uc^{-1}),\quad u,c\in G.\\
(P5)\;&\iota_\alpha:=\frac{1}{|G|}\sum_{g\in G}\chi_\alpha(g^2),\qquad
\sum_{g\in G}\chi_\alpha(g^2c^{-1})=\frac{|G|}{d_\alpha}\iota_\alpha\chi_\alpha(c).\\
(P6)\;&\text{The general loop-symmetric block formula is }\bigoplus_{\varphi\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\varphi)||G|^{|V_X|}\times |r_Y^{-1}(\varphi)||G|^{|V_Y|}}.
\end{align*}

\section*{Derivation}
For a boundary label $c\in G$, the fiber over $c$ in either Mobius band is
\begin{align*}
r_S^{-1}(c)&=\{g\in G:g^2=c\} &&\text{by (P2)}\\
|r_S^{-1}(c)|&=K(c),\qquad S\in\{X,Y\} &&\text{by (P3).}
\end{align*}
The character expression for $K(c)$ is
\begin{align*}
K(c)
&=\sum_{g\in G}\delta_{g^2,c} &&\text{by (P3)}\\
&=\sum_{g\in G}\frac{1}{|G|}\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\chi_\alpha(g^2c^{-1}) &&\text{by (P4)}\\
&=\sum_{\alpha\in\operatorname{Rep}(G)}\frac{d_\alpha}{|G|}\sum_{g\in G}\chi_\alpha(g^2c^{-1}) &&\text{reorder finite sums}\\
&=\sum_{\alpha\in\operatorname{Rep}(G)}\frac{d_\alpha}{|G|}\left(\frac{|G|}{d_\alpha}\iota_\alpha\chi_\alpha(c)\right) &&\text{by (P5)}\\
&=\sum_{\alpha\in\operatorname{Rep}(G)}\iota_\alpha\chi_\alpha(c). &&\text{cancel factors}
\end{align*}
Substituting $|A|=1$ and $|r_X^{-1}(c)|=|r_Y^{-1}(c)|=K(c)$ into (P6) gives
\begin{align*}
\mathcal{W}_{N_2}
&=\bigoplus_{c\in G:K(c)>0}\bigoplus_{j=1}^{|G|^{|V_\partial|-1}}
\mathbb{C}^{K(c)|G|^{|V_X|}\times K(c)|G|^{|V_Y|}}. &&\text{substitution into (P6)}
\end{align*}

\section*{Final Result}
\[
\boxed{\mathcal{W}_{N_2}=\bigoplus_{c\in G:K(c)>0}\bigoplus_{j=1}^{|G|^{|V_\partial|-1}}
\mathbb{C}^{K(c)|G|^{|V_X|}\times K(c)|G|^{|V_Y|}},\quad K(c)=\sum_\alpha\iota_\alpha\chi_\alpha(c)}
\]
\hfill$\blacksquare$

core_reasoning_7:
\section*{Claim}
For the genus-one Heegaard splitting of the lens space $L(q;p)$, with $p,q$ coprime and $q\ge 1$, the topological block size is one on both sides and the number of blocks is
\[
|\operatorname{Im}|=|\operatorname{Hom}(\pi_1(L(q;p)),G)|=|\{g\in G:g^q=1\}|=\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\nu_q^\alpha,
\]
where $\nu_q^\alpha:=|G|^{-1}\sum_{g\in G}\chi_\alpha(g^q)$.

\section*{Premises}
\begin{align*}
(P1)\;&L(q;p)=X\cup_\partial Y\text{ is a genus-one Heegaard splitting into two solid tori.}\\
(P2)\;&r_X\text{ and }r_Y\text{ are injective for this splitting.}\\
(P3)\;&\pi_1(L(q;p))\cong \mathbb{Z}_q=\langle x:x^q=1\rangle.\\
(P4)\;&\operatorname{Hom}(\mathbb{Z}_q,G)\cong \{g\in G:g^q=1\}.\\
(P5)\;&\delta_{u,1}=\frac{1}{|G|}\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\chi_\alpha(u),\quad u\in G.\\
(P6)\;&\nu_q^\alpha:=\frac{1}{|G|}\sum_{g\in G}\chi_\alpha(g^q).\\
(P7)\;&\text{The general loop-symmetric topological block multiplicity is indexed by }\varphi\in\operatorname{Im}\text{ with row size }|r_X^{-1}(\varphi)|\text{ and column size }|r_Y^{-1}(\varphi)|.
\end{align*}

\section*{Derivation}
Because $r_X$ and $r_Y$ are injective,
\begin{align*}
|r_X^{-1}(\varphi)|&=1,\qquad |r_Y^{-1}(\varphi)|=1 &&\text{by (P2).}
\end{align*}
The admissible image is determined by homomorphisms from the fundamental group of the glued manifold:
\begin{align*}
|\operatorname{Im}|
&=|\operatorname{Hom}(\pi_1(L(q;p)),G)| &&\text{by (P7) and the gluing constraint}\\
&=|\operatorname{Hom}(\mathbb{Z}_q,G)| &&\text{by (P3)}\\
&=|\{g\in G:g^q=1\}| &&\text{by (P4).}
\end{align*}
Now evaluate this cardinality by characters:
\begin{align*}
|\{g\in G:g^q=1\}|
&=\sum_{g\in G}\delta_{g^q,1} &&\text{indicator of the constraint}\\
&=\sum_{g\in G}\frac{1}{|G|}\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\chi_\alpha(g^q) &&\text{by (P5)}\\
&=\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\left(\frac{1}{|G|}\sum_{g\in G}\chi_\alpha(g^q)\right) &&\text{reorder finite sums}\\
&=\sum_{\alpha\in\operatorname{Rep}(G)}d_\alpha\nu_q^\alpha &&\text{by (P6).}
\end{align*}

\section*{Final Result}
\[
\boxed{|r_X^{-1}(\varphi)|=|r_Y^{-1}(\varphi)|=1,\qquad |\operatorname{Im}|=|\{g\in G:g^q=1\}|=\sum_\alpha d_\alpha\nu_q^\alpha}
\]
\hfill$\blacksquare$

core_reasoning_8:
\section*{Claim}
After imposing gauge invariance on the loop-symmetric block structure, the topological part of the coefficient matrix is
\[
\bigoplus_{[\varphi]\in\operatorname{Im}/G^{|A|}}\mathbf{1}_{|[\varphi]|}\otimes
\left(\bigoplus_{\alpha_\varphi\in\operatorname{Rep}(G_\varphi)}
\mathbb{C}^{x_{\alpha_\varphi}\times y_{\alpha_\varphi}}\otimes \mathbf{1}_{d_{\alpha_\varphi}}\right),
\]
where $G_\varphi:=\{g\in G^{|A|}:g\cdot\varphi=\varphi\}$ and $x_{\alpha_\varphi},y_{\alpha_\varphi}$ are multiplicities of $\alpha_\varphi$ in the row and column permutation representations.

\section*{Premises}
\begin{align*}
(P1)\;&G^{|A|}\text{ acts on Hom labels by }(g\cdot\phi)(f_{ij})=g_j\phi(f_{ij})g_i^{-1}.\\
(P2)\;&G_\varphi:=\{g\in G^{|A|}:g\cdot\varphi=\varphi\},\qquad [\varphi]:=G^{|A|}\cdot\varphi.\\
(P3)\;&D_\varphi^X,D_\varphi^Y\text{ are the induced row and column permutation representations of }G_\varphi.\\
(P4)\;&g\cdot W_\varphi=D_\varphi^X(g)W_\varphi D_\varphi^Y(g)^{\dagger},\qquad g\in G_\varphi.\\
(P5)\;&D_\varphi^X(g)=\bigoplus_{\alpha_\varphi}\mathbf{1}_{x_{\alpha_\varphi}}\otimes D^{\alpha_\varphi}(g),\qquad
D_\varphi^Y(g)=\bigoplus_{\alpha_\varphi}\mathbf{1}_{y_{\alpha_\varphi}}\otimes D^{\alpha_\varphi}(g).\\
(P6)\;&\text{If }T\text{ satisfies }D^X(g)T=TD^Y(g)\text{ for all }g\in G_\varphi\text{ and (P5) holds, then }\\
&\{T:D^X(g)T=TD^Y(g)\ \forall g\}
=\bigoplus_{\alpha_\varphi}\mathbb{C}^{x_{\alpha_\varphi}\times y_{\alpha_\varphi}}\otimes \mathbf{1}_{d_{\alpha_\varphi}}.\\
(P7)\;&\text{Gauge-equivalent block labels in the same orbit }[\varphi]\text{ are identified, producing a factor }\mathbf{1}_{|[\varphi]|}.
\end{align*}

\section*{Derivation}
Gauge invariance of a block $W_\varphi$ means
\begin{align*}
W_\varphi&=g\cdot W_\varphi &&\text{definition of invariance}\\
&=D_\varphi^X(g)W_\varphi D_\varphi^Y(g)^{\dagger} &&\text{by (P4)}
\end{align*}
for every $g\in G_\varphi$. Since $D_\varphi^Y(g)$ is unitary,
\begin{align*}
W_\varphi D_\varphi^Y(g)&=D_\varphi^X(g)W_\varphi &&\text{right-multiply by }D_\varphi^Y(g).
\end{align*}
Thus $W_\varphi$ is an intertwiner from $D_\varphi^Y$ to $D_\varphi^X$. Using the irreducible decompositions,
\begin{align*}
D_\varphi^X(g)&=\bigoplus_{\alpha_\varphi}\mathbf{1}_{x_{\alpha_\varphi}}\otimes D^{\alpha_\varphi}(g) &&\text{by (P5)}\\
D_\varphi^Y(g)&=\bigoplus_{\alpha_\varphi}\mathbf{1}_{y_{\alpha_\varphi}}\otimes D^{\alpha_\varphi}(g) &&\text{by (P5).}
\end{align*}
Therefore the invariant vector space in the block is
\begin{align*}
\mathcal{T}_\varphi
&:=\{W_\varphi:W_\varphi D_\varphi^Y(g)=D_\varphi^X(g)W_\varphi\ \forall g\in G_\varphi\} &&\text{intertwiner space}\\
&=\bigoplus_{\alpha_\varphi\in\operatorname{Rep}(G_\varphi)}
\mathbb{C}^{x_{\alpha_\varphi}\times y_{\alpha_\varphi}}\otimes \mathbf{1}_{d_{\alpha_\varphi}} &&\text{by (P6).}
\end{align*}
Finally, the full gauge-invariant topological space is obtained by summing over distinct gauge orbits and inserting the orbit-identification degeneracy:
\begin{align*}
\mathcal{W}_{\mathrm{top}}^{\mathrm{gauge}}
