\begin{align*}
(P1)\;&\rho_X\propto \mathbf{1}_{|[\varphi]|}\otimes \mathbf{1}_{d_{\alpha_{[\varphi]}}}\otimes \mathbf{1}_{|G|^{|V_\partial|-|A|}}\text{ for a rank-one minimally entangled block.}\\
(P2)\;&D:=|[\varphi]|d_{\alpha_{[\varphi]}}|G|^{|V_\partial|-|A|}.\\
(P3)\;&\operatorname{Tr}\rho_X=1.\\
(P4)\;&S(\rho_X):=-\operatorname{Tr}(\rho_X\ln\rho_X).\\
(P5)\;&\text{The area-law boundary term is }|V_\partial|\ln |G|.\\
(P6)\;&\Gamma:=|V_\partial|\ln |G|-S(\rho_X).
\end{align*}

\section*{Derivation}
From (P1) and (P2), $\rho_X$ is proportional to the identity on a $D$-dimensional support. Therefore
\begin{align*}
\rho_X&=\lambda\mathbf{1}_D &&\text{for some scalar }\lambda.\\
\operatorname{Tr}\rho_X&=\lambda D &&\text{trace of }\mathbf{1}_D\\
1&=\lambda D &&\text{by (P3)}\\
\lambda&=D^{-1}. &&\text{solve for }\lambda
\end{align*}
Hence the entropy is
\begin{align*}
S(\rho_X)
&=-\operatorname{Tr}(D^{-1}\mathbf{1}_D\ln(D^{-1}\mathbf{1}_D)) &&\text{by (P4)}\\
&=-D\cdot D^{-1}\ln(D^{-1}) &&\text{all }D\text{ eigenvalues equal }D^{-1}\\
&=\ln D &&\text{since }-\ln(D^{-1})=\ln D\\
&=\ln\left(|[\varphi]|d_{\alpha_{[\varphi]}}|G|^{|V_\partial|-|A|}\right) &&\text{by (P2)}\\
&=\ln\left(|[\varphi]|d_{\alpha_{[\varphi]}}\right)+(|V_\partial|-|A|)\ln |G|. &&\text{logarithm product rule}
\end{align*}
