&=|V_\partial|\ln |G|-S(\rho_X) &&\text{by (P6)}\\
&=|V_\partial|\ln |G|-\ln\left(|[\varphi]|d_{\alpha_{[\varphi]}}\right)-(|V_\partial|-|A|)\ln |G| &&\text{substitute }S(\rho_X)\\
