S_{(g,\beta),(1,1)}^{-1}&=\frac{|C_g|}{d_\beta} &&\text{by (P9) and inversion}\\
\left(\frac{|C_g|}{d_\beta}\right)^{k+n-2}
&=\left(S_{(g,\beta),(1,1)}^{-1}\right)^{k+n-2} &&\text{substitution}\\
&=S_{(g,\beta),(1,1)}^{2-k-n}. &&\text{integer-exponent rule}
\end{align*}
Therefore
\begin{align*}
x_{\alpha_\varphi}
&=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^k S_{(g,\beta),(1,1)}^{2-k-n}\prod_{j=1}^nS_{(g,\beta),(c_j,\alpha_j)}. &&\text{substitution}
\end{align*}
For the closed case $n=0$, remove boundary labels:
\begin{align*}
K_k
&=x_{\emptyset} &&\text{by (P8)}\\
&=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^k S_{(g,\beta),(1,1)}^{2-k} &&\text{set }n=0\text{ and use the empty product}\\
&=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^k\left(\frac{d_\beta}{|C_g|}\right)^{2-k} &&\text{by (P6)}\\
&=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^k\left(\frac{|C_g|}{d_\beta}\right)^{k-2}. &&\text{reciprocal exponent rule}
\end{align*}

\section*{Final Result}
\[
\boxed{\begin{gathered}
x_{\alpha_\varphi}=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}
\iota_\beta^k S_{(g,\beta),(1,1)}^{2-k-n}\prod_{j=1}^nS_{(g,\beta),(c_j,\alpha_j)},\\
K_k=\sum_{[g]}\sum_{\beta\in\operatorname{Rep}(C_g)}\iota_\beta^k\left(\frac{|C_g|}{d_\beta}\right)^{k-2}.
\end{gathered}}
\]
\hfill$\blacksquare$

