\section*{Claim}
Let a closed non-orientable surface be obtained by gluing two orientable surfaces with $n$ boundary circles,
\[
M=N_{2\gamma_X+2\gamma_Y+2n-2},\qquad X=\Sigma_{\gamma_X,n},\qquad Y=\Sigma_{\gamma_Y,n},\qquad \partial=\bigsqcup_{i=1}^n S^1.
\]
Let $s=(s_1,\ldots,s_n)\in\{\pm1\}^n$ record whether the $i$th boundary gluing preserves or reverses the boundary holonomy, and define $c^s:=(c_1^{s_1},\ldots,c_n^{s_n})$. Then the loop-symmetric coefficient matrix has block structure
\[
\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c^s)|G|^{|V_Y|}},
\]
where
\[
R_{\gamma,n}(c):=\sum_{\alpha\in\operatorname{Rep}(G)}\left(\frac{|G|}{d_\alpha}\right)^{2\gamma+n-2}\prod_{i=1}^n\chi_\alpha(c_i)
\]
and $\operatorname{Im}:=\{c\in G^n:R_{\gamma_X,n}(c)>0\text{ and }R_{\gamma_Y,n}(c^s)>0\}$.

\section*{Premises}
\begin{align*}
(P1)\;&G\text{ is finite, }A\subset\partial\text{ contains one base point on each boundary component, so }|A|=n.\\
(P2)\;&\text{The general loop-symmetric block formula is}\\
&\bigoplus_{\eta\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\eta)||G|^{|V_X|}\times |r_Y^{-1}(\eta)||G|^{|V_Y|}}.\\
(P3)\;&\text{A boundary label is }c=(c_1,\ldots,c_n)\in G^n.\\
(P4)\;&\text{For }X=\Sigma_{\gamma_X,n},\quad |r_X^{-1}(c)|=R_{\gamma_X,n}(c).\\
(P5)\;&\text{The sign data changes the }Y\text{-boundary label from }c\text{ to }c^s=(c_1^{s_1},\ldots,c_n^{s_n}).\\
(P6)\;&\text{For }Y=\Sigma_{\gamma_Y,n},\quad |r_Y^{-1}(c)|=R_{\gamma_Y,n}(c^s)\text{ after the gluing convention in (P5).}\\
(P7)\;&R_{\gamma,n}(u):=\sum_{\alpha\in\operatorname{Rep}(G)}\left(\frac{|G|}{d_\alpha}\right)^{2\gamma+n-2}\prod_{i=1}^n\chi_\alpha(u_i).\\
(P8)\;&\operatorname{Im}:=\{c\in G^n:R_{\gamma_X,n}(c)>0\text{ and }R_{\gamma_Y,n}(c^s)>0\}.
\end{align*}

\section*{Derivation}
Substitute the number of boundary components into the geometric multiplicity:
\begin{align*}
|G|^{|V_\partial|-|A|}
&=|G|^{|V_\partial|-n} &&\text{by (P1).}
\end{align*}
Now specialize the general block formula to the boundary label $c\in G^n$:
\begin{align*}
&\bigoplus_{\eta\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\eta)||G|^{|V_X|}\times |r_Y^{-1}(\eta)||G|^{|V_Y|}} &&\text{by (P2)}\\
&=\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{|r_X^{-1}(c)||G|^{|V_X|}\times |r_Y^{-1}(c)||G|^{|V_Y|}} &&\text{by (P1),(P3),(P8)}\\
&=\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c^s)|G|^{|V_Y|}} &&\text{by (P4),(P5),(P6).}
\end{align*}
The explicit form of $R_{\gamma,n}$ is exactly the class-function count in (P7), and the image restriction is (P8).

\section*{Final Result}
\[
\boxed{\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times R_{\gamma_Y,n}(c^s)|G|^{|V_Y|}}}
\]
\hfill$\blacksquare$

