\section*{Claim}
For a bipartition of a closed non-orientable surface into one orientable and one non-orientable subsystem,
\[
M=N_{2\gamma_X+k_Y+2n-2},\qquad X=\Sigma_{\gamma_X,n},\qquad Y=N_{k_Y,n},\qquad \partial=\bigsqcup_{i=1}^n S^1,
\]
with $k_Y,n\ge 1$, the loop-symmetric coefficient matrix has block structure
\[
\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times K_{k_Y,n}(c)|G|^{|V_Y|}},
\]
where
\[
K_{k,n}(c):=\sum_{\alpha\in\operatorname{Rep}(G)}\iota_\alpha^k\left(\frac{|G|}{d_\alpha}\right)^{k+n-2}\prod_{i=1}^n\chi_\alpha(c_i),
\qquad
\iota_\alpha:=\frac{1}{|G|}\sum_{g\in G}\chi_\alpha(g^2).
\]
Moreover, if $k:=2\gamma_X+k_Y+2n-2$, the topological degree count satisfies
\[
|G|^n K_{k,0}=\sum_{c\in G^n}R_{\gamma_X,n}(c)K_{k_Y,n}(c).
\]

\section*{Premises}
\begin{align*}
(P1)\;&A\subset\partial\text{ has one base point on each of the }n\text{ boundary components, hence }|A|=n.\\
(P2)\;&\text{The general loop-symmetric block formula is}\\
&\bigoplus_{\eta\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\eta)||G|^{|V_X|}\times |r_Y^{-1}(\eta)||G|^{|V_Y|}}.\\
(P3)\;&\text{Boundary labels are }c=(c_1,\ldots,c_n)\in G^n.\\
(P4)\;&\text{For }X=\Sigma_{\gamma_X,n},\quad |r_X^{-1}(c)|=R_{\gamma_X,n}(c).\\
(P5)\;&\text{For }Y=N_{k_Y,n},\quad |r_Y^{-1}(c)|=K_{k_Y,n}(c).\\
(P6)\;&R_{\gamma,n}(c):=\sum_{\alpha\in\operatorname{Rep}(G)}\left(\frac{|G|}{d_\alpha}\right)^{2\gamma+n-2}\prod_{i=1}^n\chi_\alpha(c_i).\\
(P7)\;&K_{k,n}(c):=\sum_{\alpha\in\operatorname{Rep}(G)}\iota_\alpha^k\left(\frac{|G|}{d_\alpha}\right)^{k+n-2}\prod_{i=1}^n\chi_\alpha(c_i).\\
(P8)\;&\iota_\alpha:=|G|^{-1}\sum_{g\in G}\chi_\alpha(g^2).\\
(P9)\;&\operatorname{Im}:=\{c\in G^n:R_{\gamma_X,n}(c)>0\text{ and }K_{k_Y,n}(c)>0\}.\\
(P10)\;&\text{The closed surface has }k:=2\gamma_X+k_Y+2n-2\text{ crosscaps.}\\
(P11)\;&\text{Counting the same fiber product over boundary labels gives }|G|^nK_{k,0}=\sum_{c\in G^n}|r_X^{-1}(c)||r_Y^{-1}(c)|.
\end{align*}

\section*{Derivation}
First specialize the general block formula:
\begin{align*}
&\bigoplus_{\eta\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-|A|}}
\mathbb{C}^{|r_X^{-1}(\eta)||G|^{|V_X|}\times |r_Y^{-1}(\eta)||G|^{|V_Y|}} &&\text{by (P2)}\\
&=\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{|r_X^{-1}(c)||G|^{|V_X|}\times |r_Y^{-1}(c)||G|^{|V_Y|}} &&\text{by (P1),(P3),(P9)}\\
&=\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times K_{k_Y,n}(c)|G|^{|V_Y|}} &&\text{by (P4),(P5).}
\end{align*}
Next count the topological degrees of freedom in the closed glued surface:
\begin{align*}
|G|^nK_{k,0}
&=\sum_{c\in G^n}|r_X^{-1}(c)||r_Y^{-1}(c)| &&\text{by (P10),(P11)}\\
&=\sum_{c\in G^n}R_{\gamma_X,n}(c)K_{k_Y,n}(c). &&\text{by (P4),(P5)}
\end{align*}
Definitions (P6)--(P8) give the explicit character formulas for $R_{\gamma,n}$, $K_{k,n}$, and $\iota_\alpha$.

\section*{Final Result}
\[
\boxed{\begin{gathered}
\bigoplus_{c\in\operatorname{Im}}\bigoplus_{j=1}^{|G|^{|V_\partial|-n}}
\mathbb{C}^{R_{\gamma_X,n}(c)|G|^{|V_X|}\times K_{k_Y,n}(c)|G|^{|V_Y|}},\\
|G|^n K_{2\gamma_X+k_Y+2n-2,0}=\sum_{c\in G^n}R_{\gamma_X,n}(c)K_{k_Y,n}(c).
\end{gathered}}
\]
\hfill$\blacksquare$
